// Coticula site — generated by site/build.py. Edit site/src/*, not site/dist/worker.js.
const A = __ASSETS__;
const WHEEL_NAME = __WHEEL_NAME__;
const WHEEL_B64 = __WHEEL_B64__;
const SUMS = __SUMS__;
const ORIGIN = "https://coticula.kineticdevops.com";
const ROLES = new Set(["", "mcp", "skills", "apps", "security", "other"]);
const EMAIL = /^[^\s@]{1,64}@[^\s@]{1,190}\.[^\s@]{2,}$/;

let wheelBytes = null;
function wheel() {
  if (!wheelBytes) wheelBytes = Uint8Array.from(atob(WHEEL_B64), (c) => c.charCodeAt(0));
  return wheelBytes;
}

const SEC = {
  "Content-Security-Policy": "default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Frame-Options": "DENY",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
  "Strict-Transport-Security": "max-age=31536000",
  "X-Robots-Tag": "noindex", // remove at public launch (also robots.txt + meta tags)
};

function res(body, type, extra = {}, status = 200) {
  return new Response(body, { status, headers: { ...SEC, "Content-Type": type, ...extra } });
}
function json(obj, status = 200) {
  return res(JSON.stringify(obj), "application/json; charset=utf-8", { "Cache-Control": "no-store" }, status);
}

async function waitlist(req, env) {
  if (req.method !== "POST") return json({ message: "Method not allowed." }, 405);
  const origin = req.headers.get("Origin");
  if (origin && origin !== ORIGIN) return json({ message: "Forbidden." }, 403);
  if (!(req.headers.get("Content-Type") || "").includes("application/json")) return json({ message: "Expected JSON." }, 415);
  const raw = await req.text();
  if (raw.length > 2000) return json({ message: "Too large." }, 413);
  let data;
  try { data = JSON.parse(raw); } catch { return json({ message: "Invalid request." }, 400); }
  if (data.website) return json({ message: "You're on the list." }); // honeypot: pretend success
  const email = String(data.email || "").trim().toLowerCase();
  const role = String(data.role || "");
  if (!EMAIL.test(email)) return json({ message: "Please enter a valid email address." }, 400);
  if (!ROLES.has(role)) return json({ message: "Invalid option." }, 400);
  if (!env.WAITLIST) return json({ message: "Signups are paused — please try again later." }, 503);
  const key = "email:" + email;
  if (await env.WAITLIST.get(key)) return json({ message: "You're already on the list — thanks!" });
  await env.WAITLIST.put(key, JSON.stringify({ ts: new Date().toISOString(), role, country: (req.cf && req.cf.country) || "" }));
  return json({ message: "You're on the list. We'll email you when there's something to try." });
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const p = url.pathname.replace(/\/+$/, "") || "/";
    const html = "text/html; charset=utf-8";
    const cache = { "Cache-Control": "public, max-age=300" };
    switch (p) {
      case "/":
      case "/index.html": return res(A.index, html, cache);
      case "/docs": return res(A.docs, html, cache);
      case "/style.css": return res(A.css, "text/css; charset=utf-8", cache);
      case "/app.js": return res(A.js, "text/javascript; charset=utf-8", cache);
      case "/install.sh": return res(A.install, "text/x-shellscript; charset=utf-8", { "Cache-Control": "no-cache" });
      case "/dl/SHA256SUMS": return res(SUMS, "text/plain; charset=utf-8", { "Cache-Control": "no-cache" });
      case "/robots.txt": return res("User-agent: *\nDisallow: /\n", "text/plain");
      case "/api/waitlist": return waitlist(req, env);
    }
    if (p === "/dl/" + WHEEL_NAME || p === "/dl/latest.whl") {
      return res(wheel(), "application/zip", {
        "Content-Disposition": `attachment; filename="${WHEEL_NAME}"`,
        "Cache-Control": "public, max-age=86400",
      });
    }
    return res("Not found", "text/plain; charset=utf-8", {}, 404);
  },
};
